begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values('b3000000-0000-4000-8000-000000000001','pet-profile@invalid.test');
insert into public.app_members(id,role,display_name) values('b3000000-0000-4000-8000-000000000001','admin','Pets admin');
set local request.jwt.claim.sub='b3000000-0000-4000-8000-000000000001';
create function pg_temp.cmd(p jsonb,v integer default null) returns uuid language sql as $$select (app_command(gen_random_uuid(),'save_client',p,v)->>'id')::uuid$$;
create temporary table fixture(id uuid);
insert into fixture select pg_temp.cmd(jsonb_build_object('name','Pet owner','pets',jsonb_build_array(jsonb_build_object('name','Nube','species','gato','weight_kg','4','diet','Sin pollo','notes','Rescatada','age_years','3','age_recorded_on','2026-01-30','photo_data_url','data:image/jpeg;base64,/9j/AA=='))));
select is((select pets->0->>'notes' from clients where id=(select id from fixture)),'Rescatada','pet annotations persist');
select is((select pets->0->>'age_recorded_on' from clients where id=(select id from fixture)),'2026-01-30','age observation date persists');
select is((select pets->0->>'photo_data_url' from clients where id=(select id from fixture)),'data:image/jpeg;base64,/9j/AA==','bounded JPEG data persists');
do $$begin perform pg_temp.cmd(jsonb_build_object('id',(select id from fixture),'name','Changed owner'),1);end$$;
select is((select pets->0->>'age_recorded_on' from clients where id=(select id from fixture)),'2026-01-30','unrelated client edits preserve age observation date');
select is((select x->'pets'->0->>'notes' from jsonb_array_elements(app_snapshot()->'clients') x where x->>'id'=(select id::text from fixture)),'Rescatada','snapshot returns pet metadata');
select is((select x->'pets'->0->>'photo_data_url' from jsonb_array_elements(app_export()->'raw_tables'->'clients') x where x->>'id'=(select id::text from fixture)),'data:image/jpeg;base64,/9j/AA==','backup retains photo');
select throws_like($$select pg_temp.cmd('{"name":"Invalid","pets":[{"name":"Pet","age_years":"3"}]}')$$,'%edad requiere fecha%','age must include observation date');
select throws_like($$select pg_temp.cmd('{"name":"Invalid","pets":[{"name":"Pet","age_years":"-1","age_recorded_on":"2026-01-30"}]}')$$,'%edad inválida%','negative ages rejected');
select throws_like($$select pg_temp.cmd('{"name":"Invalid","pets":[{"name":"Pet","age_years":"51","age_recorded_on":"2026-01-30"}]}')$$,'%edad inválida%','out of range ages rejected');
select throws_like($$select pg_temp.cmd('{"name":"Invalid","pets":[{"name":"Pet","age_years":"3","age_recorded_on":"2026-02-30"}]}')$$,'%fecha de edad inválida%','invalid calendar dates rejected');
select throws_like($$select pg_temp.cmd('{"name":"Invalid","pets":[{"name":"Pet","photo_data_url":"data:image/svg+xml,<svg/>"}]}')$$,'%foto de mascota inválida%','SVG and external image URLs rejected');
select throws_like($$select pg_temp.cmd(jsonb_build_object('name','Large','pets',jsonb_build_array(jsonb_build_object('name','Pet','photo_data_url','data:image/jpeg;base64,/9j/'||repeat('A',550000)))))$$,'%foto de mascota inválida%','oversized photo rejected');
select lives_ok($$select pg_temp.cmd('{"name":"Legacy","pets":[{"name":"Pet","diet":"","weight_kg":null}]}')$$,'legacy pets without new metadata still save');
select * from finish();
rollback;
